"""Optional RFQ disclosure of a cheaper live rival price, with its actual package.

Input threads must be the coordinator's snapshot for this case/session. No cached,
archived, inferred, or alternative offer is presented as a live standing quote.
This is evidence decoration only; it never changes or accepts any term sheet.
"""

import json
import math

from .claims import MAX_CHECKED, offer_claim, verify


def _standing(events):
    event = next((e for e in reversed(events) if e.get("from") != "buyer"), {})
    if event.get("status") not in {"open", "final_offer"}:
        return None
    sheets = event.get("term_sheets") or []
    if not sheets:
        return None
    sheet = sheets[0]
    terms = sheet.get("terms") or {}
    price = terms.get("unit_price")
    if not isinstance(price, int | float) or isinstance(price, bool) or not math.isfinite(price) or price <= 0:
        return None
    if not isinstance(sheet.get("term_sheet_id"), str):
        return None
    return event, sheet, terms


def enrich(case, threads, recipient, move):
    """Return (unchanged or decorated move, public provenance or None).

A lower nominal price is a discussion point, never a claim of equivalent or
lower total cost. The exact quoted non-price fields and unresolved fields travel
with it. In particular a supplier's 52-day quote stays 52 days, even when the
buyer's permitted options are 42 and 56 days. One offer ID per recipient history.
"""
    message = move.get("message") or {}
    suppliers, parts = case.get("suppliers") or [], case.get("parts") or []
    if (case.get("type") != "rfq" or len(parts) != 1 or recipient not in suppliers
            or move.get("supplier_id") != recipient or message.get("action")
            or not message.get("term_sheets")):
        return move, None
    refs = message.get("refs") or []
    if len(set(refs)) >= MAX_CHECKED:
        return move, None
    own = _standing(threads.get(recipient, []))
    if own is None:
        return move, None
    used = set(refs)
    for event in threads.get(recipient, []):
        if event.get("from") == "buyer":
            used.update(event.get("refs") or [])
    candidates = []
    for source in suppliers:
        if source == recipient:
            continue
        rival = _standing(threads.get(source, []))
        if rival is None:
            continue
        event, sheet, terms = rival
        oid, price = sheet["term_sheet_id"], terms["unit_price"]
        if (oid in used or not oid.startswith(f"offer:{source.removeprefix('sup:')}-")
                or price >= own[2]["unit_price"] - 0.005):
            continue
        # Source scope comes from this live thread, never a package fact with the same ID.
        fact = {"supplier": source, "part": parts[0], "unit_price": price,
                "price_unit": 1, "currency": "EUR"}
        claim = offer_claim(oid, price, source, recipient, parts[0])
        if not verify(claim, {oid: fact}, case=case):
            continue
        # Quote only schema fields, not arbitrary supplier strings or hidden model state.
        allowed = {"payment_days", "lead_time_days", "volume_per_year", "contract_months",
                   "effective_date", "index_clause", "incoterm", "tooling_eur", "ppm_commitment",
                   "chargeback_eur_per_complaint"}
        nonprice = {k: v for k, v in terms.items() if k in allowed}
        missing = sorted(k for k in case.get("negotiable", []) if k != "unit_price" and k not in terms)
        qualifier = " Quoted non-price terms: " + json.dumps(nonprice, sort_keys=True, allow_nan=False) + "."
        if missing:
            qualifier += " Not specified on that sheet: " + ", ".join(missing) + "."
        qualifier += (" This is a different package, not a claim of equivalent terms."
                      " Can you improve the attached package in light of this competing quote?")
        candidates.append((price, oid, claim, qualifier, source, nonprice, missing))
    if not candidates:
        return move, None
    _, oid, claim, qualifier, source, nonprice, missing = min(candidates, key=lambda c: c[:2])
    decorated = {**move, "message": {**message,
                 "body": message.get("body", "") + "\n\n" + claim.sentence + qualifier,
                 "refs": [*refs, oid]}}
    return decorated, {"case_id": case.get("case_id"), "part": parts[0], "recipient": recipient,
                       "source_supplier": source, "offer_id": oid, "unit_price": claim.figure,
                       "quoted_nonprice": nonprice, "unspecified": missing}
