from copy import deepcopy

import pytest

from negotiator.rival_evidence import enrich


def state():
    case = {"case_id": "case:T", "type": "rfq", "parts": ["part:T"],
            "suppliers": ["sup:A", "sup:B", "sup:C"],
            "negotiable": ["unit_price", "payment_days", "lead_time_days"]}
    def quote(sid, price, **terms):
        return {"from": "sales", "status": "open", "term_sheets": [
            {"term_sheet_id": f"offer:{sid}-0", "terms": {"unit_price": price, **terms}}]}
    threads = {"sup:A": [quote("A", 36)],
               "sup:B": [quote("B", 31.5, lead_time_days=52)],
               "sup:C": [quote("C", 38)]}
    move = {"supplier_id": "sup:A", "message": {"body": "Our proposed package.",
            "term_sheets": [{"terms": {"unit_price": 30, "lead_time_days": 42, "payment_days": 30}}]}}
    return case, threads, move


def test_actual_rival_terms_stay_distinct_from_proposed_terms():
    case, threads, move = state()
    before = deepcopy((threads, move))
    out, provenance = enrich(case, threads, "sup:A", move)
    assert out["message"]["term_sheets"] == move["message"]["term_sheets"]
    assert '"lead_time_days": 52' in out["message"]["body"]
    assert 'payment_days' in out["message"]["body"]  # explicitly unspecified
    assert 'EUR 31.50' in out["message"]["body"]
    assert out["message"]["refs"] == ["offer:B-0"]
    assert provenance["source_supplier"] == "sup:B"
    assert provenance["recipient"] == "sup:A"
    assert (threads, move) == before


def test_citation_recovery_is_scoped_to_recipient():
    case, threads, move = state()
    out, _ = enrich(case, threads, "sup:A", move)
    threads["sup:A"].append({"from": "buyer", **out["message"]})
    assert enrich(case, threads, "sup:A", move) == (move, None)
    other = {**move, "supplier_id": "sup:C"}
    assert enrich(case, threads, "sup:C", other)[1]["offer_id"] == "offer:B-0"


@pytest.mark.parametrize("status", ["walked_away", "agreed", "expired", "timed_out"])
def test_ended_rival_is_not_disclosed(status):
    case, threads, move = state()
    threads["sup:B"][-1]["status"] = status
    assert enrich(case, threads, "sup:A", move) == (move, None)


def test_historical_offer_and_cheaper_alternative_are_not_current_standing():
    case, threads, move = state()
    threads["sup:B"].append({"from": "sales", "status": "open", "term_sheets": [
        {"term_sheet_id": "offer:B-1", "terms": {"unit_price": 37}},
        {"term_sheet_id": "offer:B-1-a", "terms": {"unit_price": 29}}]})
    assert enrich(case, threads, "sup:A", move) == (move, None)


@pytest.mark.parametrize("change", ["wrong_supplier", "wrong_recipient", "other_part", "max_claims", "close"])
def test_invalid_scope_and_claim_budget_leave_move_unchanged(change):
    case, threads, move = state()
    if change == "wrong_supplier":
        threads["sup:B"][0]["term_sheets"][0]["term_sheet_id"] = "offer:Z-0"
    elif change == "wrong_recipient":
        move["supplier_id"] = "sup:Z"
    elif change == "other_part":
        case["parts"].append("part:other")
    elif change == "max_claims":
        move["message"]["refs"] = ["a", "b", "c"]
    elif change == "close":
        move["message"]["action"] = {"type": "accept"}
    assert enrich(case, threads, "sup:A", move) == (move, None)
